-- Now insert recipes
INSERT INTO recipes (name, country, continent, is_african, category, slug, summary, history, difficulty, prep_time, cook_time, servings, tags, image_url, ingredients, steps) VALUES

-- NIGERIA
('Akara and Pap', 'Nigeria', 'Africa', true, 'Breakfast', 'akara-and-pap-nigeria', 
'Crispy deep-fried bean cakes paired with smooth, warm corn pap - Nigeria''s most popular breakfast combination enjoyed across all regions.',
'Akara has been a breakfast staple in Yoruba culture for centuries. Made from peeled black-eyed peas, it represents the ingenuity of Nigerian cuisine in creating satisfying meals from simple legumes.',
'Easy', 30, 20, 4, ARRAY['breakfast', 'nigerian', 'vegetarian', 'street-food'],
'https://images.unsplash.com/photo-1604329760661-e71dc83f8f26?w=800&auto=format&fit=crop',
'[{"item":"Black-eyed peas","quantity":"2 cups","note":"soaked overnight and peeled"},{"item":"Scotch bonnet pepper","quantity":"2","note":"deseeded"},{"item":"Onion","quantity":"1 medium","note":"roughly chopped"},{"item":"Salt","quantity":"1 tsp"},{"item":"Vegetable oil","quantity":"for deep frying"},{"item":"White corn flour (pap)","quantity":"1 cup"},{"item":"Sugar","quantity":"to taste"},{"item":"Evaporated milk","quantity":"2 tbsp"}]',
'[{"step":1,"instruction":"Blend soaked and peeled black-eyed peas with scotch bonnet pepper and onion until a thick, smooth paste forms. Do not add water."},{"step":2,"instruction":"Whisk the paste vigorously for 5 minutes until light and airy. Season with salt."},{"step":3,"instruction":"Heat vegetable oil to 350°F (175°C). Drop spoonfuls of batter into hot oil."},{"step":4,"instruction":"Fry until golden brown on all sides, about 3-4 minutes. Drain on paper towels."},{"step":5,"instruction":"For pap: Mix corn flour with cold water to form a smooth paste. Pour boiling water over it while stirring continuously until thick."},{"step":6,"instruction":"Add sugar and evaporated milk to pap. Serve warm alongside akara."}]'),

('Yam Pottage', 'Nigeria', 'Africa', true, 'Lunch', 'yam-pottage-nigeria',
'Asaro - chunky yam pieces simmered in a rich pepper and palm oil sauce with smoked fish, a satisfying Nigerian lunch.',
'Yam pottage or Asaro is a Yoruba dish that celebrates the yam, considered the king of crops in West Africa. Every October, the New Yam Festival marks the harvest season.',
'Easy', 15, 35, 4, ARRAY['lunch', 'nigerian', 'one-pot', 'yam'],
'https://images.unsplash.com/photo-1574484284002-952d92456975?w=800&auto=format&fit=crop',
'[{"item":"White yam","quantity":"1 kg","note":"peeled and cubed"},{"item":"Palm oil","quantity":"3 tbsp"},{"item":"Tomatoes","quantity":"4","note":"blended"},{"item":"Scotch bonnet pepper","quantity":"2","note":"blended"},{"item":"Onion","quantity":"1 large","note":"chopped"},{"item":"Smoked fish","quantity":"200g","note":"deboned"},{"item":"Crayfish","quantity":"2 tbsp","note":"ground"},{"item":"Seasoning cubes","quantity":"2"},{"item":"Salt","quantity":"to taste"},{"item":"Spinach","quantity":"1 cup","note":"optional"}]',
'[{"step":1,"instruction":"Boil yam cubes in salted water until half-cooked, about 10 minutes."},{"step":2,"instruction":"Add blended tomatoes, peppers, onion, and palm oil to the pot."},{"step":3,"instruction":"Add smoked fish, ground crayfish, and seasoning cubes. Stir gently."},{"step":4,"instruction":"Cook on medium heat for 20 minutes until yam is soft and sauce is thick."},{"step":5,"instruction":"Add spinach if using, stir, and cook for 2 more minutes. Serve hot."}]'),

('Efo Riro', 'Nigeria', 'Africa', true, 'Dinner', 'efo-riro-nigeria',
'Rich Yoruba-style spinach stew cooked with assorted meats, stockfish, and locust beans in a pepper and palm oil base.',
'Efo Riro means "stirred leafy vegetable" in Yoruba. It is a prestigious dinner dish served at celebrations and family gatherings, showcasing the diversity of Yoruba cooking with its complex layers of flavor.',
'Medium', 30, 45, 6, ARRAY['dinner', 'nigerian', 'yoruba', 'spinach', 'stew'],
'https://images.unsplash.com/photo-1512058564366-18510be2db19?w=800&auto=format&fit=crop',
'[{"item":"Spinach or African spinach (efo tete)","quantity":"500g","note":"washed and chopped"},{"item":"Palm oil","quantity":"4 tbsp"},{"item":"Assorted meat (beef, tripe, cow foot)","quantity":"500g","note":"cooked"},{"item":"Stockfish","quantity":"200g","note":"soaked and deboned"},{"item":"Scotch bonnet peppers","quantity":"4","note":"blended"},{"item":"Tomatoes","quantity":"3","note":"blended"},{"item":"Red bell pepper","quantity":"2","note":"blended"},{"item":"Locust beans (iru)","quantity":"2 tbsp"},{"item":"Onions","quantity":"2","note":"chopped"},{"item":"Crayfish","quantity":"3 tbsp","note":"ground"},{"item":"Seasoning cubes","quantity":"3"},{"item":"Salt","quantity":"to taste"}]',
'[{"step":1,"instruction":"Bleach palm oil by heating until clear. Add chopped onions and fry until translucent."},{"step":2,"instruction":"Add blended tomatoes, peppers, and bell pepper. Fry for 15-20 minutes until oil floats on top."},{"step":3,"instruction":"Add locust beans, ground crayfish, seasoning cubes, and salt. Stir well."},{"step":4,"instruction":"Add cooked assorted meat and stockfish. Simmer for 10 minutes."},{"step":5,"instruction":"Add chopped spinach and stir. Cook for 3-5 minutes - do not overcook."},{"step":6,"instruction":"Serve hot with pounded yam, amala, or eba."}]'),

('Zobo Drink', 'Nigeria', 'Africa', true, 'Drinks', 'zobo-drink-nigeria',
'Vibrant ruby-red hibiscus flower drink infused with ginger, cloves, and pineapple - Nigeria''s most popular homemade beverage.',
'Zobo is derived from the Hausa word for hibiscus. It has been brewed across Northern Nigeria for generations and is now enjoyed nationwide as a refreshing, naturally healthy drink.',
'Easy', 15, 30, 8, ARRAY['drinks', 'nigerian', 'non-alcoholic', 'hibiscus', 'healthy'],
'https://images.unsplash.com/photo-1544145945-f90425340c7e?w=800&auto=format&fit=crop',
'[{"item":"Dried hibiscus flowers (zobo leaves)","quantity":"3 cups"},{"item":"Fresh ginger","quantity":"100g","note":"sliced"},{"item":"Pineapple","quantity":"1","note":"peeled and chopped"},{"item":"Whole cloves","quantity":"1 tbsp"},{"item":"Sugar or honey","quantity":"to taste"},{"item":"Water","quantity":"3 liters"},{"item":"Cucumber","quantity":"1","note":"optional, for garnish"},{"item":"Orange","quantity":"1","note":"juiced, optional"}]',
'[{"step":1,"instruction":"Wash dried hibiscus flowers thoroughly under running water."},{"step":2,"instruction":"Place flowers in a large pot with ginger, pineapple, and cloves. Add water."},{"step":3,"instruction":"Bring to a boil, then reduce heat and simmer for 20-30 minutes until deeply red."},{"step":4,"instruction":"Strain through a fine mesh sieve, pressing to extract all flavor."},{"step":5,"instruction":"Sweeten with sugar or honey while warm. Add orange juice if using."},{"step":6,"instruction":"Cool completely and refrigerate. Serve ice cold with cucumber slices."}]'),

('Kunu Aya', 'Nigeria', 'Africa', true, 'Drinks', 'kunu-aya-nigeria',
'Creamy, naturally sweet tiger nut milk blended with dates and coconut - a nutritious Nigerian dairy-free beverage.',
'Tiger nut milk has been consumed in Northern Nigeria for centuries. Known locally as Kunu Aya, it is valued for its nutritional benefits and is a popular street drink sold by Hausa vendors.',
'Easy', 20, 0, 6, ARRAY['drinks', 'nigerian', 'dairy-free', 'healthy', 'vegan'],
'https://images.unsplash.com/photo-1550583724-b2692b85b150?w=800&auto=format&fit=crop',
'[{"item":"Tiger nuts","quantity":"2 cups","note":"soaked overnight"},{"item":"Dates","quantity":"10","note":"pitted"},{"item":"Coconut","quantity":"1/2 cup","note":"fresh or dried"},{"item":"Ginger","quantity":"1 inch piece"},{"item":"Water","quantity":"4 cups"},{"item":"Vanilla extract","quantity":"1 tsp","note":"optional"}]',
'[{"step":1,"instruction":"Drain soaked tiger nuts and rinse well."},{"step":2,"instruction":"Blend tiger nuts, dates, coconut, and ginger with water until very smooth."},{"step":3,"instruction":"Strain through a cheesecloth or nut milk bag, squeezing out all liquid."},{"step":4,"instruction":"Add vanilla extract if using. Adjust sweetness with more dates if needed."},{"step":5,"instruction":"Refrigerate for at least 2 hours. Shake well before serving ice cold."}]'),

('Chapman', 'Nigeria', 'Africa', true, 'Drinks', 'chapman-nigeria',
'Nigeria''s iconic party cocktail/mocktail - a festive blend of Fanta, Sprite, grenadine, and Angostura bitters with fresh fruits.',
'Chapman was invented in the 1960s at Ikoyi Club in Lagos. Originally an exclusive club drink, it has become Nigeria''s most famous non-alcoholic cocktail, present at every celebration.',
'Easy', 10, 0, 4, ARRAY['drinks', 'nigerian', 'cocktail', 'party', 'non-alcoholic'],
'https://images.unsplash.com/photo-1513558161293-cdaf765ed2fd?w=800&auto=format&fit=crop',
'[{"item":"Fanta orange","quantity":"500ml"},{"item":"Sprite","quantity":"500ml"},{"item":"Grenadine syrup","quantity":"3 tbsp"},{"item":"Angostura bitters","quantity":"4 dashes"},{"item":"Cucumber","quantity":"1","note":"sliced"},{"item":"Orange","quantity":"1","note":"sliced"},{"item":"Lemon","quantity":"1","note":"sliced"},{"item":"Ice cubes","quantity":"plenty"},{"item":"Ribena blackcurrant","quantity":"2 tbsp","note":"optional"}]',
'[{"step":1,"instruction":"Fill a large pitcher with ice cubes."},{"step":2,"instruction":"Pour in Fanta and Sprite. Add grenadine syrup and Angostura bitters."},{"step":3,"instruction":"Add Ribena if using for deeper color and flavor."},{"step":4,"instruction":"Add sliced cucumber, orange, and lemon. Stir gently."},{"step":5,"instruction":"Serve immediately in tall glasses with fruit garnish."}]'),

('Masa', 'Nigeria', 'Africa', true, 'Breakfast', 'masa-northern-nigeria',
'Fermented rice cakes from Northern Nigeria - crispy golden edges with a soft, slightly tangy center, served with sugar or spicy sauce.',
'Masa (also called Waina) is a Hausa breakfast delicacy cooked in a special cast-iron mold called kasko. The fermentation process gives it a distinctive tang.',
'Medium', 480, 20, 6, ARRAY['breakfast', 'nigerian', 'hausa', 'fermented', 'rice'],
'https://images.unsplash.com/photo-1567364816519-cbc9c4a0a736?w=800&auto=format&fit=crop',
'[{"item":"Short-grain rice","quantity":"3 cups","note":"soaked 6 hours"},{"item":"Cooked rice","quantity":"1/2 cup","note":"for starter"},{"item":"Sugar","quantity":"2 tbsp"},{"item":"Yeast","quantity":"1 tsp"},{"item":"Salt","quantity":"1/2 tsp"},{"item":"Warm water","quantity":"as needed"},{"item":"Vegetable oil","quantity":"for cooking"}]',
'[{"step":1,"instruction":"Blend soaked rice with cooked rice starter and warm water until smooth."},{"step":2,"instruction":"Add yeast and sugar. Cover and ferment for 6-8 hours or overnight until bubbly."},{"step":3,"instruction":"Season with salt. The batter should be pourable but not too thin."},{"step":4,"instruction":"Heat oiled masa pan (or use a muffin tin). Pour batter into each mold."},{"step":5,"instruction":"Cook until bottom is golden, flip and cook the other side. Serve warm with sugar or yaji pepper."}]'),

('Pepper Soup', 'Nigeria', 'Africa', true, 'Dinner', 'pepper-soup-nigeria',
'Intensely aromatic and spicy broth loaded with goat meat and traditional pepper soup spices - the ultimate Nigerian comfort dinner.',
'Pepper soup is believed to have medicinal properties and is often served to nursing mothers and those recovering from illness. Each ethnic group has their own variation using local spice blends.',
'Medium', 20, 60, 6, ARRAY['dinner', 'nigerian', 'soup', 'spicy', 'goat'],
'https://images.unsplash.com/photo-1547592166-23ac45744acd?w=800&auto=format&fit=crop',
'[{"item":"Goat meat","quantity":"1 kg","note":"cut into pieces"},{"item":"Pepper soup spice mix","quantity":"3 tbsp"},{"item":"Scotch bonnet pepper","quantity":"3","note":"whole"},{"item":"Onions","quantity":"2","note":"quartered"},{"item":"Scent leaves or basil","quantity":"1 cup"},{"item":"Ehuru (calabash nutmeg)","quantity":"1","note":"crushed"},{"item":"Uziza seeds","quantity":"1 tsp","note":"ground"},{"item":"Salt","quantity":"to taste"},{"item":"Seasoning cubes","quantity":"2"},{"item":"Water","quantity":"6 cups"}]',
'[{"step":1,"instruction":"Wash goat meat and place in pot with onions, seasoning cubes, and salt. Add water and boil until tender, about 40 minutes."},{"step":2,"instruction":"Add pepper soup spice, crushed ehuru, and ground uziza. Stir well."},{"step":3,"instruction":"Add whole scotch bonnet peppers (do not blend for authentic texture)."},{"step":4,"instruction":"Simmer for 15 minutes until broth is fragrant and slightly thickened."},{"step":5,"instruction":"Add scent leaves, stir, and cook for 2 more minutes. Serve hot as is or with boiled yam."}]'),

('Moi Moi', 'Nigeria', 'Africa', true, 'Lunch', 'moi-moi-nigeria',
'Steamed savory bean pudding made from blended black-eyed peas with peppers, eggs, and corned beef - a protein-rich Nigerian lunch.',
'Moi Moi dates back to the pre-colonial era in Yoruba cuisine. Traditionally wrapped in leaves and steamed, it is served at celebrations and as a nutritious everyday meal.',
'Medium', 30, 45, 8, ARRAY['lunch', 'nigerian', 'beans', 'steamed', 'protein'],
'https://images.unsplash.com/photo-1512058564366-18510be2db19?w=800&auto=format&fit=crop',
'[{"item":"Black-eyed peas","quantity":"2 cups","note":"soaked and peeled"},{"item":"Red bell pepper","quantity":"2","note":"chopped"},{"item":"Scotch bonnet pepper","quantity":"1"},{"item":"Onion","quantity":"1 large"},{"item":"Palm oil","quantity":"3 tbsp"},{"item":"Crayfish","quantity":"2 tbsp","note":"ground"},{"item":"Seasoning cubes","quantity":"2"},{"item":"Eggs","quantity":"3","note":"boiled and halved"},{"item":"Corned beef","quantity":"100g","note":"optional"},{"item":"Salt","quantity":"to taste"},{"item":"Warm water","quantity":"1 cup"}]',
'[{"step":1,"instruction":"Blend peeled black-eyed peas with peppers, onion, and warm water until very smooth."},{"step":2,"instruction":"Add palm oil, ground crayfish, seasoning cubes, and salt. Mix thoroughly."},{"step":3,"instruction":"The mixture should be pourable. Adjust with water if too thick."},{"step":4,"instruction":"Pour into greased ramekins or foil cups. Add boiled egg halves and corned beef pieces into each."},{"step":5,"instruction":"Steam for 45 minutes until firm and set. Test with a toothpick - it should come out clean."},{"step":6,"instruction":"Let cool slightly before unmolding. Serve warm or at room temperature."}]'),

-- GHANA
('Hausa Koko', 'Ghana', 'Africa', true, 'Breakfast', 'hausa-koko-ghana',
'Spiced millet porridge with ginger, cloves, and chili - Ghana''s most popular breakfast porridge sold by street vendors every morning.',
'Hausa Koko originated from the Hausa people of Northern Ghana. It has become the nation''s favorite breakfast, with vendors setting up as early as 4 AM to serve commuters.',
'Easy', 15, 25, 4, ARRAY['breakfast', 'ghanaian', 'porridge', 'millet', 'spiced'],
'https://images.unsplash.com/photo-1517673400267-0251440c45dc?w=800&auto=format&fit=crop',
'[{"item":"Millet flour","quantity":"1 cup"},{"item":"Fresh ginger","quantity":"2 inches","note":"grated"},{"item":"Cloves","quantity":"4"},{"item":"Chili pepper","quantity":"1","note":"dried"},{"item":"Water","quantity":"4 cups"},{"item":"Sugar","quantity":"to taste"},{"item":"Evaporated milk","quantity":"optional"}]',
'[{"step":1,"instruction":"Mix millet flour with 1 cup cold water to make a smooth paste."},{"step":2,"instruction":"Boil remaining water with ginger, cloves, and dried chili for 10 minutes. Strain."},{"step":3,"instruction":"Pour the spiced water back into the pot and bring to a boil."},{"step":4,"instruction":"Slowly pour in the millet paste while stirring continuously to prevent lumps."},{"step":5,"instruction":"Cook on low heat for 15 minutes, stirring frequently, until thick and smooth."},{"step":6,"instruction":"Serve hot with sugar and koose (bean fritters) on the side."}]'),

('Banku and Tilapia', 'Ghana', 'Africa', true, 'Lunch', 'banku-and-tilapia-ghana',
'Fermented corn and cassava dough served with crispy grilled tilapia and fiery pepper sauce - Ghana''s beloved lunch combination.',
'Banku is the national dish of the Ga and Ewe peoples. The combination with grilled tilapia became iconic along the coast, where freshly caught fish meets traditional fermented dough.',
'Medium', 30, 45, 4, ARRAY['lunch', 'ghanaian', 'fish', 'fermented', 'grilled'],
'https://images.unsplash.com/photo-1504674900247-0877df9cc836?w=800&auto=format&fit=crop',
'[{"item":"Fermented corn dough","quantity":"2 cups"},{"item":"Cassava dough","quantity":"1 cup"},{"item":"Water","quantity":"3 cups"},{"item":"Whole tilapia","quantity":"2","note":"cleaned and scored"},{"item":"Tomatoes","quantity":"4"},{"item":"Scotch bonnet peppers","quantity":"3"},{"item":"Onions","quantity":"2"},{"item":"Ginger","quantity":"1 inch"},{"item":"Salt","quantity":"to taste"},{"item":"Vegetable oil","quantity":"for grilling"}]',
'[{"step":1,"instruction":"Mix corn dough and cassava dough with water in a pot. Cook on medium heat, stirring continuously with a wooden spatula."},{"step":2,"instruction":"Keep stirring vigorously for 20-25 minutes until the dough is smooth, shiny, and pulls away from the pot."},{"step":3,"instruction":"Season tilapia with salt, ginger, and oil. Grill over charcoal or in oven until crispy and cooked through."},{"step":4,"instruction":"For pepper sauce: char tomatoes, peppers, and onions. Blend coarsely with salt."},{"step":5,"instruction":"Shape banku into balls. Serve with grilled tilapia and pepper sauce."}]'),

('Groundnut Soup', 'Ghana', 'Africa', true, 'Dinner', 'groundnut-soup-ghana',
'Creamy, rich peanut soup with tender chicken pieces - a warming Ghanaian dinner served with fufu.',
'Groundnut soup (Nkatekwan) is one of Ghana''s most cherished soups, enjoyed across all ethnic groups. Peanuts were introduced to West Africa from South America in the 16th century and quickly became integral to the cuisine.',
'Medium', 20, 50, 6, ARRAY['dinner', 'ghanaian', 'peanut', 'chicken', 'soup'],
'https://images.unsplash.com/photo-1547592166-23ac45744acd?w=800&auto=format&fit=crop',
'[{"item":"Chicken","quantity":"1 whole","note":"cut into pieces"},{"item":"Smooth peanut butter","quantity":"1 cup"},{"item":"Tomatoes","quantity":"4","note":"blended"},{"item":"Onion","quantity":"1 large","note":"blended"},{"item":"Scotch bonnet pepper","quantity":"2"},{"item":"Ginger","quantity":"1 inch","note":"grated"},{"item":"Garlic","quantity":"3 cloves"},{"item":"Salt","quantity":"to taste"},{"item":"Water","quantity":"6 cups"}]',
'[{"step":1,"instruction":"Season chicken with salt, ginger, garlic, and onion. Add water and boil until tender, about 30 minutes."},{"step":2,"instruction":"Add blended tomatoes and cook for 15 minutes until oil rises."},{"step":3,"instruction":"Dissolve peanut butter in warm broth and add to the soup, stirring well."},{"step":4,"instruction":"Add whole scotch bonnet peppers. Simmer for 20 minutes until soup is thick and rich."},{"step":5,"instruction":"Adjust seasoning. Serve hot with fufu or rice balls."}]'),

('Sobolo', 'Ghana', 'Africa', true, 'Drinks', 'sobolo-ghana',
'Ghana''s refreshing hibiscus drink with ginger, cloves, and dried fruit - served ice cold at every gathering.',
'Sobolo is Ghana''s version of the West African hibiscus drink. It became commercially popular in the 2000s and is now sold by street vendors, restaurants, and packaged brands across the country.',
'Easy', 10, 20, 8, ARRAY['drinks', 'ghanaian', 'hibiscus', 'non-alcoholic', 'refreshing'],
'https://images.unsplash.com/photo-1544145945-f90425340c7e?w=800&auto=format&fit=crop',
'[{"item":"Dried hibiscus petals","quantity":"2 cups"},{"item":"Fresh ginger","quantity":"3 inches","note":"sliced"},{"item":"Whole cloves","quantity":"1 tbsp"},{"item":"Dried anise","quantity":"1 tsp"},{"item":"Sugar","quantity":"1 cup","note":"or to taste"},{"item":"Water","quantity":"2.5 liters"},{"item":"Pineapple juice","quantity":"1 cup","note":"optional"}]',
'[{"step":1,"instruction":"Rinse hibiscus petals well. Place in a large pot with ginger, cloves, and anise."},{"step":2,"instruction":"Add water and bring to a boil. Reduce heat and simmer for 15-20 minutes."},{"step":3,"instruction":"Strain through fine mesh. Add sugar while warm and stir to dissolve."},{"step":4,"instruction":"Add pineapple juice if using. Cool to room temperature."},{"step":5,"instruction":"Refrigerate until very cold. Serve over ice."}]'),

('Kelewele', 'Ghana', 'Africa', true, 'Snack', 'kelewele-ghana',
'Spicy fried plantain cubes marinated in ginger, chili, and cloves - Ghana''s favorite evening street snack.',
'Kelewele is a beloved Ghanaian street food, particularly popular as an evening snack. The unique spice blend differentiates it from simple fried plantains found elsewhere in West Africa.',
'Easy', 15, 10, 4, ARRAY['snack', 'ghanaian', 'plantain', 'spicy', 'street-food'],
'https://images.unsplash.com/photo-1528735602780-2552fd46c7af?w=800&auto=format&fit=crop',
'[{"item":"Ripe plantains","quantity":"4","note":"firm but ripe"},{"item":"Fresh ginger","quantity":"2 inches","note":"grated"},{"item":"Chili flakes","quantity":"1 tsp"},{"item":"Ground cloves","quantity":"1/4 tsp"},{"item":"Nutmeg","quantity":"1/4 tsp"},{"item":"Salt","quantity":"1/2 tsp"},{"item":"Vegetable oil","quantity":"for frying"}]',
'[{"step":1,"instruction":"Peel plantains and cut into 1-inch cubes."},{"step":2,"instruction":"Mix ginger, chili flakes, cloves, nutmeg, and salt in a bowl."},{"step":3,"instruction":"Toss plantain cubes in the spice mixture. Let marinate for 15 minutes."},{"step":4,"instruction":"Deep fry in hot oil until golden brown and crispy, about 3-4 minutes."},{"step":5,"instruction":"Drain on paper towels. Serve hot with roasted peanuts."}]'),

('Waakye', 'Ghana', 'Africa', true, 'Lunch', 'waakye-ghana',
'Rice and black-eyed peas cooked with dried millet stalks giving a distinctive burgundy color - Ghana''s favorite all-day meal.',
'Waakye originated from Northern Ghana but has conquered the entire country. The distinctive color comes from dried sorghum or millet stalks, and it is served with an elaborate spread of sides.',
'Medium', 20, 45, 6, ARRAY['lunch', 'ghanaian', 'rice', 'beans', 'one-pot'],
'https://images.unsplash.com/photo-1512058564366-18510be2db19?w=800&auto=format&fit=crop',
'[{"item":"Rice","quantity":"2 cups"},{"item":"Black-eyed peas","quantity":"1 cup","note":"soaked overnight"},{"item":"Dried millet stalks","quantity":"3","note":"for color"},{"item":"Baking soda","quantity":"1/2 tsp"},{"item":"Salt","quantity":"to taste"},{"item":"Water","quantity":"6 cups"},{"item":"Spaghetti","quantity":"200g","note":"for serving"},{"item":"Shito (pepper sauce)","quantity":"for serving"},{"item":"Boiled eggs","quantity":"for serving"}]',
'[{"step":1,"instruction":"Boil dried millet stalks in water for 10 minutes to release color. Strain and reserve the red water."},{"step":2,"instruction":"Parboil black-eyed peas in the red water with baking soda for 15 minutes."},{"step":3,"instruction":"Add washed rice to the beans. Add more red water if needed to cover. Add salt."},{"step":4,"instruction":"Cook on low heat until rice and beans are tender and water is absorbed, about 25 minutes."},{"step":5,"instruction":"Serve with boiled spaghetti, shito pepper sauce, boiled eggs, and fried plantains."}]'),

('Koose', 'Ghana', 'Africa', true, 'Breakfast', 'koose-ghana',
'Ghanaian black-eyed pea fritters, crispy on the outside and fluffy inside - the perfect breakfast companion to Hausa Koko.',
'Koose (also called Kosai) is the Ghanaian variant of bean fritters found across West Africa. Sold by street vendors alongside porridge, it is an essential part of the Ghanaian morning routine.',
'Easy', 20, 15, 4, ARRAY['breakfast', 'ghanaian', 'beans', 'fritters', 'street-food'],
'https://images.unsplash.com/photo-1604329760661-e71dc83f8f26?w=800&auto=format&fit=crop',
'[{"item":"Black-eyed peas","quantity":"2 cups","note":"soaked and peeled"},{"item":"Onion","quantity":"1"},{"item":"Scotch bonnet pepper","quantity":"1"},{"item":"Salt","quantity":"1 tsp"},{"item":"Vegetable oil","quantity":"for deep frying"}]',
'[{"step":1,"instruction":"Blend peeled black-eyed peas with onion and pepper until smooth. Do not add water."},{"step":2,"instruction":"Whisk batter vigorously until light and fluffy. Season with salt."},{"step":3,"instruction":"Heat oil to 350°F. Drop tablespoons of batter into hot oil."},{"step":4,"instruction":"Fry until golden brown all over, about 4 minutes."},{"step":5,"instruction":"Drain on paper towels. Serve hot with Hausa Koko or bread."}]'),

-- SENEGAL
('Café Touba', 'Senegal', 'Africa', true, 'Drinks', 'cafe-touba-senegal',
'Senegal''s beloved spiced coffee infused with selim pepper (djar) and cloves - a spiritual and cultural beverage.',
'Named after the holy city of Touba, this coffee was popularized by the Mouride brotherhood. It is deeply tied to Senegalese Sufi culture and is served at religious ceremonies and daily life.',
'Easy', 5, 15, 4, ARRAY['drinks', 'senegalese', 'coffee', 'spiced', 'traditional'],
'https://images.unsplash.com/photo-1509042239860-f550ce710b93?w=800&auto=format&fit=crop',
'[{"item":"Green coffee beans","quantity":"200g"},{"item":"Selim pepper (djar)","quantity":"2 tbsp"},{"item":"Whole cloves","quantity":"1 tsp"},{"item":"Sugar","quantity":"to taste"},{"item":"Water","quantity":"4 cups"}]',
'[{"step":1,"instruction":"Roast green coffee beans with selim pepper and cloves in a dry pan until dark and aromatic."},{"step":2,"instruction":"Grind roasted beans and spices together to a fine powder."},{"step":3,"instruction":"Brew using a filter: place grounds in filter, pour boiling water through slowly."},{"step":4,"instruction":"Sweeten generously with sugar - Café Touba is traditionally very sweet."},{"step":5,"instruction":"Serve hot in small glasses. Can be served with evaporated milk."}]'),

('Lakh', 'Senegal', 'Africa', true, 'Breakfast', 'lakh-senegal',
'Senegalese millet porridge topped with sweetened fermented milk and vanilla - a nourishing breakfast or dessert.',
'Lakh (also called Laakh or Thiakry) is a treasured Senegalese comfort food. It is often prepared for Eid celebrations and family gatherings, combining the nutrition of millet with the tang of fermented milk.',
'Easy', 10, 20, 4, ARRAY['breakfast', 'senegalese', 'millet', 'porridge', 'dessert'],
'https://images.unsplash.com/photo-1517673400267-0251440c45dc?w=800&auto=format&fit=crop',
'[{"item":"Millet couscous","quantity":"2 cups"},{"item":"Fermented milk (lait caillé)","quantity":"2 cups"},{"item":"Sugar","quantity":"1/2 cup"},{"item":"Vanilla extract","quantity":"1 tsp"},{"item":"Nutmeg","quantity":"1/4 tsp"},{"item":"Raisins","quantity":"1/4 cup","note":"optional"},{"item":"Pineapple","quantity":"1/2 cup","note":"diced, optional"}]',
'[{"step":1,"instruction":"Steam millet couscous until fluffy and tender, about 15 minutes."},{"step":2,"instruction":"Fluff with a fork and let cool slightly."},{"step":3,"instruction":"Mix fermented milk with sugar, vanilla, and nutmeg until smooth."},{"step":4,"instruction":"Combine millet with the sweetened milk. Add raisins and pineapple if using."},{"step":5,"instruction":"Serve at room temperature or chilled. Adjust sweetness to taste."}]'),

('Yassa Poulet', 'Senegal', 'Africa', true, 'Dinner', 'yassa-poulet-senegal',
'Grilled chicken smothered in a caramelized lemon and onion sauce - Senegal''s most celebrated dinner dish.',
'Yassa originated from the Casamance region in southern Senegal. The dish showcases the brilliance of Senegalese cuisine with its balance of tangy citrus and sweet caramelized onions over smoky grilled chicken.',
'Medium', 60, 45, 4, ARRAY['dinner', 'senegalese', 'chicken', 'lemon', 'onion'],
'https://images.unsplash.com/photo-1598103442097-8b74394b95c6?w=800&auto=format&fit=crop',
'[{"item":"Whole chicken","quantity":"1","note":"cut into pieces"},{"item":"Onions","quantity":"6 large","note":"thinly sliced"},{"item":"Lemons","quantity":"4","note":"juiced"},{"item":"Dijon mustard","quantity":"2 tbsp"},{"item":"Vegetable oil","quantity":"4 tbsp"},{"item":"Garlic","quantity":"4 cloves","note":"minced"},{"item":"Green olives","quantity":"1/2 cup"},{"item":"Scotch bonnet pepper","quantity":"1"},{"item":"Bay leaves","quantity":"2"},{"item":"Salt and pepper","quantity":"to taste"},{"item":"Rice","quantity":"for serving"}]',
'[{"step":1,"instruction":"Marinate chicken in lemon juice, mustard, half the onions, garlic, salt, and pepper for at least 2 hours (overnight is best)."},{"step":2,"instruction":"Remove chicken from marinade (reserve it). Grill or broil chicken until charred and cooked through."},{"step":3,"instruction":"In a large pot, heat oil and caramelize remaining onions until deep golden, about 20 minutes."},{"step":4,"instruction":"Add reserved marinade, bay leaves, whole scotch bonnet, and olives. Simmer for 15 minutes."},{"step":5,"instruction":"Add grilled chicken to the onion sauce. Cook together for 10 minutes so flavors meld."},{"step":6,"instruction":"Serve over white rice with the abundant onion sauce."}]'),

('Bissap Juice', 'Senegal', 'Africa', true, 'Drinks', 'bissap-juice-senegal',
'Senegalese hibiscus drink with fresh mint, vanilla, and orange blossom water - Africa''s most elegant refreshment.',
'Bissap is considered the national drink of Senegal. The addition of mint and orange blossom water distinguishes the Senegalese preparation from other West African hibiscus drinks.',
'Easy', 10, 15, 6, ARRAY['drinks', 'senegalese', 'hibiscus', 'mint', 'refreshing'],
'https://images.unsplash.com/photo-1544145945-f90425340c7e?w=800&auto=format&fit=crop',
'[{"item":"Dried hibiscus flowers","quantity":"2 cups"},{"item":"Fresh mint leaves","quantity":"1/2 cup"},{"item":"Vanilla pod","quantity":"1","note":"split"},{"item":"Orange blossom water","quantity":"1 tbsp"},{"item":"Sugar","quantity":"3/4 cup"},{"item":"Water","quantity":"2 liters"},{"item":"Pineapple","quantity":"1 cup","note":"diced, for garnish"}]',
'[{"step":1,"instruction":"Boil hibiscus flowers with mint and vanilla pod for 15 minutes."},{"step":2,"instruction":"Strain and add sugar while warm. Stir until dissolved."},{"step":3,"instruction":"Add orange blossom water. Cool to room temperature."},{"step":4,"instruction":"Refrigerate until very cold. Serve with pineapple chunks and ice."}]'),

('Mafé', 'Senegal', 'Africa', true, 'Lunch', 'mafe-senegal',
'Hearty peanut butter stew with beef, sweet potato, and cassava in a tomato-peanut sauce - Senegal''s comfort lunch.',
'Mafé (also called Domoda in Gambia) is a Mandinka dish that spread across West Africa. It represents the perfect fusion of indigenous peanuts with imported tomatoes, creating a uniquely West African flavor.',
'Medium', 20, 60, 6, ARRAY['lunch', 'senegalese', 'peanut', 'beef', 'stew'],
'https://images.unsplash.com/photo-1547592166-23ac45744acd?w=800&auto=format&fit=crop',
'[{"item":"Beef","quantity":"500g","note":"cubed"},{"item":"Natural peanut butter","quantity":"1 cup"},{"item":"Tomato paste","quantity":"3 tbsp"},{"item":"Onion","quantity":"1 large","note":"chopped"},{"item":"Sweet potato","quantity":"2","note":"cubed"},{"item":"Cassava","quantity":"1 cup","note":"cubed"},{"item":"Cabbage","quantity":"1/4 head","note":"quartered"},{"item":"Carrots","quantity":"2","note":"chunked"},{"item":"Scotch bonnet","quantity":"1"},{"item":"Garlic","quantity":"3 cloves"},{"item":"Salt","quantity":"to taste"},{"item":"Rice","quantity":"for serving"}]',
'[{"step":1,"instruction":"Brown beef in oil. Add onions and garlic, cook until softened."},{"step":2,"instruction":"Add tomato paste and cook for 5 minutes until darkened."},{"step":3,"instruction":"Dissolve peanut butter in 3 cups warm water. Add to pot."},{"step":4,"instruction":"Add sweet potato, cassava, carrots, and whole scotch bonnet. Simmer for 40 minutes."},{"step":5,"instruction":"Add cabbage in the last 10 minutes. Adjust seasoning."},{"step":6,"instruction":"Serve over white rice with the thick peanut sauce ladled generously."}]'),

-- IVORY COAST
('Garba', 'Ivory Coast', 'Africa', true, 'Lunch', 'garba-ivory-coast',
'Attiéké (cassava couscous) topped with fried tuna, onions, and hot pepper - Ivory Coast''s most popular street lunch.',
'Garba is named after the Ghanaian and Nigerien vendors who popularized it in Abidjan. It has become the iconic lunch of Ivorian workers and students, affordable and filling.',
'Easy', 15, 15, 4, ARRAY['lunch', 'ivorian', 'cassava', 'tuna', 'street-food'],
'https://images.unsplash.com/photo-1504674900247-0877df9cc836?w=800&auto=format&fit=crop',
'[{"item":"Attiéké (cassava couscous)","quantity":"4 cups"},{"item":"Fresh tuna steaks","quantity":"400g"},{"item":"Vegetable oil","quantity":"for frying"},{"item":"Onion","quantity":"1 large","note":"thinly sliced"},{"item":"Tomato","quantity":"2","note":"diced"},{"item":"Scotch bonnet pepper","quantity":"1","note":"minced"},{"item":"Maggi cube","quantity":"1"},{"item":"Salt","quantity":"to taste"},{"item":"Lemon","quantity":"1","note":"for serving"}]',
'[{"step":1,"instruction":"Season tuna with salt and Maggi cube. Fry in hot oil until golden and cooked through. Break into chunks."},{"step":2,"instruction":"Steam or microwave attiéké until warm and fluffy."},{"step":3,"instruction":"Mix raw sliced onions, diced tomatoes, and minced scotch bonnet with a little oil and salt."},{"step":4,"instruction":"Mound attiéké on a plate, top with fried tuna and the onion-pepper mixture."},{"step":5,"instruction":"Squeeze lemon over the top. Serve immediately."}]'),

-- MALI
('Dégué', 'Mali', 'Africa', true, 'Drinks', 'degue-mali',
'Creamy millet ball and yogurt dessert drink from Mali - sweet, tangy, and refreshing with vanilla and nutmeg.',
'Dégué is a beloved Malian dessert-drink hybrid, often served after meals or as a refreshment. The small millet balls give it a unique chewy texture that distinguishes it from simple yogurt drinks.',
'Easy', 20, 15, 6, ARRAY['drinks', 'malian', 'millet', 'yogurt', 'dessert'],
'https://images.unsplash.com/photo-1550583724-b2692b85b150?w=800&auto=format&fit=crop',
'[{"item":"Millet couscous","quantity":"1 cup","note":"fine grain"},{"item":"Plain yogurt","quantity":"2 cups"},{"item":"Evaporated milk","quantity":"1 cup"},{"item":"Sugar","quantity":"1/2 cup"},{"item":"Vanilla extract","quantity":"1 tsp"},{"item":"Nutmeg","quantity":"1/4 tsp"},{"item":"Ice cubes","quantity":"for serving"}]',
'[{"step":1,"instruction":"Steam millet couscous until tender. Let cool and break up any clumps into small balls."},{"step":2,"instruction":"Mix yogurt, evaporated milk, sugar, vanilla, and nutmeg until smooth."},{"step":3,"instruction":"Fold the cooled millet balls into the yogurt mixture."},{"step":4,"instruction":"Refrigerate for at least 1 hour to let flavors meld."},{"step":5,"instruction":"Serve cold with ice cubes. Adjust sweetness to taste."}]'),

('Tô with Okra Sauce', 'Mali', 'Africa', true, 'Dinner', 'to-okra-sauce-mali',
'Thick millet porridge served with slimy, savory okra sauce - Mali''s essential dinner staple.',
'Tô is the foundation of Malian cuisine, made from millet or sorghum flour. The communal eating of Tô with sauce represents family unity and is the most commonly eaten dinner across Mali.',
'Medium', 15, 40, 6, ARRAY['dinner', 'malian', 'millet', 'okra', 'staple'],
'https://images.unsplash.com/photo-1574484284002-952d92456975?w=800&auto=format&fit=crop',
'[{"item":"Millet flour","quantity":"2 cups"},{"item":"Water","quantity":"5 cups"},{"item":"Fresh okra","quantity":"500g","note":"chopped"},{"item":"Smoked fish","quantity":"200g"},{"item":"Onion","quantity":"1","note":"chopped"},{"item":"Tomato paste","quantity":"2 tbsp"},{"item":"Palm oil","quantity":"2 tbsp"},{"item":"Dawadawa (locust bean seasoning)","quantity":"1 tbsp"},{"item":"Salt","quantity":"to taste"}]',
'[{"step":1,"instruction":"Boil 3 cups water. Mix millet flour with 2 cups cold water to make a paste."},{"step":2,"instruction":"Slowly pour millet paste into boiling water, stirring vigorously with a wooden stick."},{"step":3,"instruction":"Cook and stir for 20 minutes until very thick and pulls from the pot. Shape into dome on a plate."},{"step":4,"instruction":"For sauce: Sauté onion in palm oil. Add tomato paste and cook 5 minutes."},{"step":5,"instruction":"Add chopped okra, smoked fish, dawadawa, and 1 cup water. Simmer 15 minutes until slimy."},{"step":6,"instruction":"Serve Tô with the okra sauce ladled over and around it."}]'),

-- GUINEA
('Fouti', 'Guinea', 'Africa', true, 'Lunch', 'fouti-guinea',
'Guinean rice with rich peanut sauce and smoked fish - a satisfying lunch enjoyed across the country.',
'Fouti is a cornerstone of Guinean home cooking. The combination of rice with peanut sauce reflects the Mandinka culinary tradition that spans Guinea, Gambia, and southern Senegal.',
'Easy', 15, 35, 4, ARRAY['lunch', 'guinean', 'rice', 'peanut', 'fish'],
'https://images.unsplash.com/photo-1512058564366-18510be2db19?w=800&auto=format&fit=crop',
'[{"item":"Long-grain rice","quantity":"2 cups"},{"item":"Peanut butter","quantity":"3/4 cup"},{"item":"Smoked fish","quantity":"200g","note":"flaked"},{"item":"Onion","quantity":"1","note":"diced"},{"item":"Tomato paste","quantity":"2 tbsp"},{"item":"Scotch bonnet pepper","quantity":"1"},{"item":"Salt","quantity":"to taste"},{"item":"Oil","quantity":"2 tbsp"},{"item":"Water","quantity":"3 cups"}]',
'[{"step":1,"instruction":"Cook rice until fluffy. Set aside."},{"step":2,"instruction":"Sauté onion in oil. Add tomato paste and cook 3 minutes."},{"step":3,"instruction":"Dissolve peanut butter in warm water. Add to pot with whole pepper."},{"step":4,"instruction":"Add flaked smoked fish. Simmer for 20 minutes until sauce thickens."},{"step":5,"instruction":"Serve rice with peanut sauce ladled over. Remove scotch bonnet before eating."}]'),

-- BURKINA FASO
('Riz Gras', 'Burkina Faso', 'Africa', true, 'Lunch', 'riz-gras-burkina-faso',
'Burkinabè one-pot seasoned rice with vegetables and beef - a celebratory lunch dish.',
'Riz Gras (fat rice) is the go-to celebration dish in Burkina Faso. Named for the generous amount of oil used, it is served at weddings, baptisms, and family feasts.',
'Medium', 20, 40, 6, ARRAY['lunch', 'burkinabe', 'rice', 'one-pot', 'celebration'],
'https://images.unsplash.com/photo-1512058564366-18510be2db19?w=800&auto=format&fit=crop',
'[{"item":"Long-grain rice","quantity":"3 cups"},{"item":"Beef","quantity":"400g","note":"cubed"},{"item":"Tomato paste","quantity":"3 tbsp"},{"item":"Carrots","quantity":"2","note":"diced"},{"item":"Green beans","quantity":"1 cup","note":"chopped"},{"item":"Cabbage","quantity":"1/4 head","note":"shredded"},{"item":"Onion","quantity":"2","note":"chopped"},{"item":"Garlic","quantity":"3 cloves"},{"item":"Vegetable oil","quantity":"1/3 cup"},{"item":"Maggi cubes","quantity":"3"},{"item":"Salt","quantity":"to taste"},{"item":"Water","quantity":"4 cups"}]',
'[{"step":1,"instruction":"Brown beef in oil. Add onions and garlic, cook until softened."},{"step":2,"instruction":"Add tomato paste and cook until deep red, about 5 minutes."},{"step":3,"instruction":"Add carrots, green beans, and cabbage. Stir well."},{"step":4,"instruction":"Add washed rice, water, and Maggi cubes. Bring to a boil."},{"step":5,"instruction":"Reduce heat, cover, and cook for 25 minutes until rice is tender and liquid absorbed."},{"step":6,"instruction":"Fluff with a fork. Serve hot garnished with fried plantains."}]'),

-- LIBERIA
('Palava Sauce', 'Liberia', 'Africa', true, 'Dinner', 'palava-sauce-liberia',
'Rich Liberian spinach and palm oil stew with smoked fish and crab - a hearty dinner over rice.',
'Palava Sauce (also called Palaver Sauce) gets its name from the Portuguese word for "discussion" - it was traditionally prepared when important family matters needed discussion over a meal.',
'Medium', 20, 40, 6, ARRAY['dinner', 'liberian', 'spinach', 'palm-oil', 'seafood'],
'https://images.unsplash.com/photo-1512058564366-18510be2db19?w=800&auto=format&fit=crop',
'[{"item":"Spinach or potato leaves","quantity":"500g","note":"chopped"},{"item":"Palm oil","quantity":"1/3 cup"},{"item":"Smoked fish","quantity":"200g","note":"deboned"},{"item":"Crab or crayfish","quantity":"200g"},{"item":"Onion","quantity":"1","note":"chopped"},{"item":"Scotch bonnet pepper","quantity":"2","note":"chopped"},{"item":"Okra","quantity":"4","note":"chopped"},{"item":"Melon seeds (egusi)","quantity":"1/4 cup","note":"ground"},{"item":"Salt","quantity":"to taste"},{"item":"Rice","quantity":"for serving"}]',
'[{"step":1,"instruction":"Heat palm oil. Sauté onions and peppers until fragrant."},{"step":2,"instruction":"Add ground melon seeds and stir for 3 minutes."},{"step":3,"instruction":"Add smoked fish, crab, and 1 cup water. Simmer for 15 minutes."},{"step":4,"instruction":"Add chopped spinach and okra. Cook for 15 minutes until greens are tender."},{"step":5,"instruction":"Adjust seasoning. Serve over steamed white rice."}]'),

('Liberian Ginger Beer', 'Liberia', 'Africa', true, 'Drinks', 'liberian-ginger-beer',
'Fiery fermented ginger drink with lime and pineapple - a staple at every Liberian celebration.',
'Ginger beer has been brewed in Liberia for generations, introduced during the colonial era and adapted with local ingredients. It is essential at holidays, weddings, and Christmas.',
'Easy', 15, 20, 8, ARRAY['drinks', 'liberian', 'ginger', 'fermented', 'spicy'],
'https://images.unsplash.com/photo-1513558161293-cdaf765ed2fd?w=800&auto=format&fit=crop',
'[{"item":"Fresh ginger","quantity":"500g","note":"peeled and grated"},{"item":"Sugar","quantity":"1.5 cups"},{"item":"Limes","quantity":"4","note":"juiced"},{"item":"Pineapple","quantity":"1 cup","note":"chopped"},{"item":"Whole cloves","quantity":"1 tsp"},{"item":"Water","quantity":"3 liters"},{"item":"Active dry yeast","quantity":"1/4 tsp","note":"for natural carbonation"}]',
'[{"step":1,"instruction":"Boil grated ginger and cloves in water for 15 minutes. Let steep for 30 minutes."},{"step":2,"instruction":"Strain through fine mesh, pressing out all liquid."},{"step":3,"instruction":"Add sugar and stir until dissolved. Add lime juice and blended pineapple."},{"step":4,"instruction":"Once cooled to lukewarm, add yeast. Stir gently."},{"step":5,"instruction":"Pour into bottles leaving headspace. Ferment at room temperature 24-48 hours."},{"step":6,"instruction":"Refrigerate to stop fermentation. Serve very cold over ice."}]'),

-- GAMBIA
('Benachin', 'Gambia', 'Africa', true, 'Lunch', 'benachin-gambia',
'Gambian one-pot rice with fish, vegetables, and tomato sauce - the country''s national lunch dish.',
'Benachin (meaning "one pot" in Wolof) is the Gambian equivalent of Senegalese Thieboudienne. Every family has their version, and it is the standard lunch served in homes and restaurants nationwide.',
'Medium', 20, 50, 6, ARRAY['lunch', 'gambian', 'rice', 'fish', 'one-pot'],
'https://images.unsplash.com/photo-1504674900247-0877df9cc836?w=800&auto=format&fit=crop',
'[{"item":"Broken rice","quantity":"3 cups"},{"item":"Whole fish (grouper or snapper)","quantity":"1 large","note":"cleaned"},{"item":"Tomato paste","quantity":"4 tbsp"},{"item":"Onion","quantity":"2","note":"chopped"},{"item":"Cabbage","quantity":"1/4 head"},{"item":"Cassava","quantity":"1 cup","note":"cubed"},{"item":"Sweet potato","quantity":"1","note":"cubed"},{"item":"Eggplant","quantity":"1","note":"cubed"},{"item":"Scotch bonnet","quantity":"2"},{"item":"Vegetable oil","quantity":"1/4 cup"},{"item":"Fish seasoning","quantity":"2 tbsp"},{"item":"Water","quantity":"4 cups"}]',
'[{"step":1,"instruction":"Season fish with salt and half the tomato paste. Fry until golden. Set aside."},{"step":2,"instruction":"In the same oil, fry onions and remaining tomato paste until deep red."},{"step":3,"instruction":"Add vegetables, water, and scotch bonnet. Bring to boil and simmer 15 minutes."},{"step":4,"instruction":"Remove vegetables and set aside. Add washed rice to the broth."},{"step":5,"instruction":"Cook rice covered on low heat for 25 minutes until tender. Arrange fish and vegetables on top."},{"step":6,"instruction":"Cover and steam for 5 minutes. Serve family-style on a large platter."}]'),

('Chereh', 'Gambia', 'Africa', true, 'Breakfast', 'chereh-gambia',
'Steamed millet couscous with sour milk and sugar - a traditional Gambian breakfast porridge.',
'Chereh is a morning staple in Gambian households, particularly in rural areas. The fermented milk gives it a distinctive tang that complements the earthy millet.',
'Easy', 10, 20, 4, ARRAY['breakfast', 'gambian', 'millet', 'porridge', 'fermented-milk'],
'https://images.unsplash.com/photo-1517673400267-0251440c45dc?w=800&auto=format&fit=crop',
'[{"item":"Millet couscous","quantity":"2 cups"},{"item":"Sour milk or buttermilk","quantity":"2 cups"},{"item":"Sugar","quantity":"1/4 cup"},{"item":"Baobab fruit powder","quantity":"1 tbsp","note":"optional"},{"item":"Salt","quantity":"pinch"}]',
'[{"step":1,"instruction":"Steam millet couscous until tender and fluffy, about 15 minutes."},{"step":2,"instruction":"Transfer to a bowl and fluff with a fork. Let cool slightly."},{"step":3,"instruction":"Pour sour milk over the millet. Add sugar and a pinch of salt."},{"step":4,"instruction":"Sprinkle baobab powder if using for extra tang and nutrition."},{"step":5,"instruction":"Mix gently and serve at room temperature or slightly chilled."}]'),

-- TOGO
('Ablo', 'Togo', 'Africa', true, 'Breakfast', 'ablo-togo',
'Steamed fermented rice cakes from Togo - soft, slightly sweet, and perfectly paired with spicy sauce.',
'Ablo is a Togolese specialty with roots in Ewe cuisine. The fermentation gives it a unique tang while steaming keeps it incredibly soft. It is eaten for breakfast or as a snack.',
'Medium', 480, 20, 8, ARRAY['breakfast', 'togolese', 'rice', 'steamed', 'fermented'],
'https://images.unsplash.com/photo-1567364816519-cbc9c4a0a736?w=800&auto=format&fit=crop',
'[{"item":"Rice flour","quantity":"2 cups"},{"item":"All-purpose flour","quantity":"1/2 cup"},{"item":"Sugar","quantity":"2 tbsp"},{"item":"Yeast","quantity":"1 tsp"},{"item":"Salt","quantity":"1/2 tsp"},{"item":"Warm water","quantity":"2 cups"},{"item":"Coconut milk","quantity":"1/2 cup"}]',
'[{"step":1,"instruction":"Mix rice flour, all-purpose flour, sugar, yeast, and salt in a bowl."},{"step":2,"instruction":"Add warm water and coconut milk. Stir until smooth batter forms."},{"step":3,"instruction":"Cover and let ferment in a warm place for 6-8 hours until doubled and bubbly."},{"step":4,"instruction":"Pour batter into greased molds (ramekins or muffin cups), filling halfway."},{"step":5,"instruction":"Steam for 15-20 minutes until firm and a toothpick comes out clean."},{"step":6,"instruction":"Serve warm with pepper sauce, tomato stew, or simply with sugar."}]'),

-- BENIN
('Akpan', 'Benin', 'Africa', true, 'Drinks', 'akpan-benin',
'Chilled fermented corn yogurt drink from Benin - tangy, sweet, and probiotic-rich.',
'Akpan is a traditional Beninese fermented beverage made from corn. It has gained popularity across West Africa as a natural probiotic drink, served chilled as a refreshing afternoon treat.',
'Easy', 20, 30, 6, ARRAY['drinks', 'beninese', 'fermented', 'corn', 'probiotic'],
'https://images.unsplash.com/photo-1550583724-b2692b85b150?w=800&auto=format&fit=crop',
'[{"item":"White corn flour","quantity":"2 cups"},{"item":"Water","quantity":"4 cups"},{"item":"Sugar","quantity":"1/2 cup"},{"item":"Vanilla extract","quantity":"1 tsp"},{"item":"Evaporated milk","quantity":"1/2 cup","note":"optional"},{"item":"Ice","quantity":"for serving"}]',
'[{"step":1,"instruction":"Mix corn flour with 2 cups water into a smooth paste."},{"step":2,"instruction":"Let ferment in a warm place for 24 hours until slightly sour."},{"step":3,"instruction":"Boil remaining water. Gradually stir in the fermented paste, cooking until thick like porridge."},{"step":4,"instruction":"Let cool completely. Add sugar, vanilla, and evaporated milk."},{"step":5,"instruction":"Blend until smooth. Refrigerate until very cold."},{"step":6,"instruction":"Serve in cups with ice. The drink should be thick but pourable."}]'),

-- NIGER
('Fura da Nono', 'Niger', 'Africa', true, 'Drinks', 'fura-da-nono-niger',
'Millet dough balls crumbled into fermented milk - Niger''s beloved nutritious drink-snack hybrid.',
'Fura da Nono is a Hausa-Fulani tradition shared across Niger, Nigeria, and neighboring countries. Fulani women are the traditional preparers and sellers, carrying calabashes on their heads.',
'Easy', 30, 15, 4, ARRAY['drinks', 'nigerien', 'millet', 'fermented-milk', 'fulani'],
'https://images.unsplash.com/photo-1550583724-b2692b85b150?w=800&auto=format&fit=crop',
'[{"item":"Millet flour","quantity":"2 cups"},{"item":"Ginger powder","quantity":"1 tsp"},{"item":"Clove powder","quantity":"1/2 tsp"},{"item":"Sugar","quantity":"2 tbsp"},{"item":"Fermented milk (nono)","quantity":"3 cups"},{"item":"Water","quantity":"1 cup"}]',
'[{"step":1,"instruction":"Mix millet flour with ginger, cloves, and sugar."},{"step":2,"instruction":"Add just enough water to form a stiff dough. Knead well for 5 minutes."},{"step":3,"instruction":"Roll into small balls. Boil in water for 10 minutes until cooked through."},{"step":4,"instruction":"Remove and let cool. Crumble fura balls into a bowl."},{"step":5,"instruction":"Pour cold fermented milk over the crumbled fura. Stir to combine."},{"step":6,"instruction":"Add more sugar if desired. Serve immediately as a cold drink-snack."}]'),

('Kilishi', 'Niger', 'Africa', true, 'Snack', 'kilishi-niger',
'Sun-dried spiced beef jerky coated in a peanut and spice paste - Niger''s traditional protein snack.',
'Kilishi is the Hausa version of jerky, perfected over centuries in the Sahel region. The peanut coating and complex spice blend make it unique among dried meats worldwide.',
'Hard', 60, 480, 8, ARRAY['snack', 'nigerien', 'beef', 'dried', 'peanut'],
'https://images.unsplash.com/photo-1529692236671-f1f6cf9683ba?w=800&auto=format&fit=crop',
'[{"item":"Beef","quantity":"1 kg","note":"sliced paper-thin"},{"item":"Roasted peanuts","quantity":"1 cup","note":"ground to paste"},{"item":"Ginger powder","quantity":"2 tbsp"},{"item":"Cayenne pepper","quantity":"1 tbsp"},{"item":"Onion powder","quantity":"1 tbsp"},{"item":"Garlic powder","quantity":"1 tsp"},{"item":"Seasoning cubes","quantity":"3","note":"crushed"},{"item":"Salt","quantity":"to taste"},{"item":"Honey","quantity":"2 tbsp"},{"item":"Water","quantity":"1/4 cup"}]',
'[{"step":1,"instruction":"Slice beef paper-thin against the grain. Lay on drying racks in the sun or use a dehydrator at 160°F for 4-6 hours until dry."},{"step":2,"instruction":"Mix ground peanut paste with all spices, honey, and water to form a thick, spreadable paste."},{"step":3,"instruction":"Dip each dried meat strip in the peanut paste, coating both sides evenly."},{"step":4,"instruction":"Return coated strips to drying racks. Dry for another 2-3 hours until paste sets."},{"step":5,"instruction":"Grill briefly over charcoal for smoky flavor, being careful not to burn the coating."},{"step":6,"instruction":"Store in airtight containers. Kilishi keeps for weeks without refrigeration."}]'),

-- SIERRA LEONE
('Cassava Leaf Stew', 'Sierra Leone', 'Africa', true, 'Dinner', 'cassava-leaf-stew-sierra-leone',
'Sierra Leone''s national dinner - finely ground cassava leaves slow-cooked with palm oil, meat, and fish.',
'Cassava Leaf is the undisputed national dish of Sierra Leone. The leaves must be pounded or ground to a fine consistency and slow-cooked for hours, a labor of love that brings families together.',
'Medium', 30, 90, 6, ARRAY['dinner', 'sierra-leonean', 'cassava', 'palm-oil', 'stew'],
'https://images.unsplash.com/photo-1512058564366-18510be2db19?w=800&auto=format&fit=crop',
'[{"item":"Cassava leaves","quantity":"500g","note":"ground or pounded"},{"item":"Palm oil","quantity":"1/2 cup"},{"item":"Beef or chicken","quantity":"400g","note":"cubed"},{"item":"Smoked fish","quantity":"200g"},{"item":"Onion","quantity":"1 large","note":"chopped"},{"item":"Scotch bonnet pepper","quantity":"2"},{"item":"Maggi cubes","quantity":"2"},{"item":"Salt","quantity":"to taste"},{"item":"Okra","quantity":"4","note":"optional, chopped"},{"item":"Rice","quantity":"for serving"}]',
'[{"step":1,"instruction":"Boil ground cassava leaves in water for 30 minutes. Drain and set aside."},{"step":2,"instruction":"Cook meat with onions, salt, and seasoning until tender."},{"step":3,"instruction":"Add palm oil and stir well. Add drained cassava leaves."},{"step":4,"instruction":"Add smoked fish, peppers, and Maggi cubes. Add 1 cup water."},{"step":5,"instruction":"Simmer on low heat for 45-60 minutes, stirring occasionally, until oil rises to the top."},{"step":6,"instruction":"Serve hot over steamed white rice."}]'),

('Poyo', 'Sierra Leone', 'Africa', true, 'Drinks', 'poyo-sierra-leone',
'Fresh palm wine tapped from palm trees - Sierra Leone''s natural alcoholic beverage with cultural significance.',
'Poyo (palm wine) is central to Sierra Leonean social life. Professional tappers climb palm trees at dawn to collect the sweet sap, which naturally ferments throughout the day.',
'Easy', 5, 0, 4, ARRAY['drinks', 'sierra-leonean', 'palm-wine', 'traditional', 'alcoholic'],
'https://images.unsplash.com/photo-1513558161293-cdaf765ed2fd?w=800&auto=format&fit=crop',
'[{"item":"Fresh palm sap (palm wine)","quantity":"2 liters","note":"from palm tree"},{"item":"Ice","quantity":"for serving"},{"item":"Lime","quantity":"1","note":"optional, for garnish"}]',
'[{"step":1,"instruction":"Palm wine is collected by a tapper who climbs the palm tree and makes an incision in the trunk or flower stalk."},{"step":2,"instruction":"A gourd or container is tied below the cut to collect the dripping sap overnight."},{"step":3,"instruction":"Fresh palm wine is sweet and mildly alcoholic (2-4%). It ferments further throughout the day."},{"step":4,"instruction":"Strain through a clean cloth to remove any debris."},{"step":5,"instruction":"Serve immediately over ice. Morning palm wine is sweeter; evening palm wine is more alcoholic."}]'),

-- CAPE VERDE
('Grogue Punch', 'Cape Verde', 'Africa', true, 'Drinks', 'grogue-punch-cape-verde',
'Cape Verdean sugar cane rum punch mixed with tropical fruits and honey - the islands'' festive cocktail.',
'Grogue is Cape Verde''s national spirit, distilled from sugar cane. The punch version, mixed with local fruits and honey, is served at festivals and celebrations on every island.',
'Easy', 10, 0, 6, ARRAY['drinks', 'cape-verdean', 'rum', 'cocktail', 'tropical'],
'https://images.unsplash.com/photo-1513558161293-cdaf765ed2fd?w=800&auto=format&fit=crop',
'[{"item":"Grogue (or white rum)","quantity":"2 cups"},{"item":"Honey","quantity":"1/4 cup"},{"item":"Lime juice","quantity":"1/2 cup"},{"item":"Passion fruit pulp","quantity":"1 cup"},{"item":"Papaya","quantity":"1 cup","note":"diced"},{"item":"Cinnamon stick","quantity":"1"},{"item":"Ice","quantity":"plenty"}]',
'[{"step":1,"instruction":"Warm honey with a splash of grogue to dissolve. Let cool."},{"step":2,"instruction":"Blend passion fruit pulp and papaya until smooth."},{"step":3,"instruction":"Combine grogue, honey mixture, lime juice, and fruit puree in a pitcher."},{"step":4,"instruction":"Add cinnamon stick and stir well. Refrigerate for 1 hour."},{"step":5,"instruction":"Serve over crushed ice. Garnish with lime wheels."}]'),

-- GUINEA-BISSAU
('Caldo de Mancarra', 'Guinea-Bissau', 'Africa', true, 'Lunch', 'caldo-de-mancarra-guinea-bissau',
'Hearty peanut soup with chicken and vegetables from Guinea-Bissau - Portuguese and African flavors united.',
'Caldo de Mancarra reflects Guinea-Bissau''s unique culinary identity, blending Portuguese cooking techniques with West African ingredients. Mancarra (peanut) is the country''s most important crop.',
'Easy', 15, 40, 4, ARRAY['lunch', 'guinea-bissau', 'peanut', 'soup', 'chicken'],
'https://images.unsplash.com/photo-1547592166-23ac45744acd?w=800&auto=format&fit=crop',
'[{"item":"Chicken thighs","quantity":"4"},{"item":"Peanut butter","quantity":"3/4 cup"},{"item":"Tomatoes","quantity":"3","note":"diced"},{"item":"Onion","quantity":"1","note":"chopped"},{"item":"Sweet potato","quantity":"1","note":"cubed"},{"item":"Garlic","quantity":"2 cloves"},{"item":"Bay leaf","quantity":"1"},{"item":"Salt and pepper","quantity":"to taste"},{"item":"Water","quantity":"5 cups"},{"item":"Rice","quantity":"for serving"}]',
'[{"step":1,"instruction":"Brown chicken thighs in a pot. Remove and set aside."},{"step":2,"instruction":"Sauté onion, garlic, and tomatoes until soft."},{"step":3,"instruction":"Dissolve peanut butter in warm water. Add to pot with bay leaf."},{"step":4,"instruction":"Return chicken, add sweet potato. Simmer 30 minutes until chicken is cooked through."},{"step":5,"instruction":"Season with salt and pepper. Serve with white rice."}]')

